window.piPull = async function () {
  var month = monthVal();
  var btn = document.getElementById('pi-pull-btn');
  if (btn) btn.disabled = true;
  msg('Pulling Airbnb VAT docs from Hosthub codes (can take several minutes)…', true);
  try {
    if (!PI.health || !PI.health.airInvList) await piHealth();
    var h = PI.health || {};
    var airbnbReservations = []
      .concat(h.airInvList || [])
      .concat(h.airCreditList || [])
      .map(function (x) {
        return {
          code: x.code,
          kind: x.kind || 'invoice',
          aptId: x.aptId || '',
          aptName: x.aptName || '',
          guestName: x.guestName || ''
        };
      })
      .filter(function (x) { return !!x.code; });
    if (!airbnbReservations.length) {
      // Server resolves from DB + live Hosthub if the browser cache is stale
      try {
        var cj = await fetch('/api/platform-invoices/airbnb-codes?month=' + encodeURIComponent(month)).then(function (r) { return r.json(); });
        if (cj && cj.ok && Array.isArray(cj.reservations) && cj.reservations.length) {
          airbnbReservations = cj.reservations;
          if (PI.health) {
            PI.health.airInvList = cj.reservations.filter(function (x) { return x.kind !== 'credit_note'; });
            PI.health.airCreditList = cj.reservations.filter(function (x) { return x.kind === 'credit_note'; });
          }
        }
      } catch (e) {}
    }
    if (!airbnbReservations.length) {
      msg('No Airbnb reservation codes for ' + month + ' — Sync Hosthub on the Dashboard, wait for it to finish, then Refresh Expect. If Expect still shows missing codes, Hosthub has no reservation_id on those bookings.', false);
      return;
    }
    var apts = (typeof S !== 'undefined' && Array.isArray(S.apts))
      ? S.apts.map(function (a) { return { aptId: a.id || a.aptId || '', aptName: a.name || a.aptName || '' }; })
      : [];
    var res = await fetch('/api/platform-invoices/pull', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ month: month, channel: 'airbnb', apartments: apts, airbnbReservations: airbnbReservations })
    });
    var r = await res.json();
    var errTxt = (r.errors || []).map(function (e) {
      return (e.channel ? (e.channel + ': ') : '') + (e.code ? (e.code + ' — ') : '') + (e.error || e.hint || '');
    }).filter(Boolean).slice(0, 4).join(' · ');
    if (!res.ok) throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (errTxt ? (' · ' + errTxt) : ''));
    var n = (r.saved || []).length;
    if (n === 0) {
      var expired = /session expired|reconnect Airbnb|OTP|Connect Airbnb session/i.test(errTxt + ' ' + (r.reconnectHint || ''));
      msg('Airbnb pull saved 0 PDFs from ' + airbnbReservations.length + ' Hosthub code(s)' +
        (errTxt ? (' — ' + errTxt) : '') +
        (r.reconnectHint ? (' — ' + r.reconnectHint) : (expired ? ' — click Connect Airbnb, enter the email code, then Pull again' : '')), false);
    } else {
      msg('Pulled ' + n + ' Airbnb PDF(s) from ' + (r.airbnbCodes || airbnbReservations.length) + ' Hosthub code(s)' +
        (errTxt ? (' · notes: ' + errTxt) : ''), true);
    }
    await piHealth();
    await piReload();
  } catch (e) { msg(e.message || String(e), false); }
  finally { if (btn) btn.disabled = false; }
};

