window.piPullParseResponse = function (res, raw) {
  var t = String(raw || '').trim();
  if (!t || /^upstream error$/i.test(t) || /gateway timeout|bad gateway/i.test(t)) {
    throw new Error('Pull was cut off by the server proxy (upstream error). The pull now runs in the background — click Pull Airbnb again to watch progress. Do not Connect again unless the session expired.');
  }
  try { return JSON.parse(t); } catch (e) {
    throw new Error('Pull returned non-JSON (' + (res && res.status) + '): ' + t.slice(0, 160));
  }
};
window.piPullFinishMsg = function (job, codeCount) {
  var errTxt = (job.errors || []).map(function (e) {
    return (e.channel ? (e.channel + ': ') : '') + (e.code ? (e.code + ' — ') : '') + (e.error || e.hint || '');
  }).filter(Boolean).slice(0, 4).join(' · ');
  var n = (job.saved || []).length;
  var codes = job.airbnbCodes || codeCount || 0;
  if (job.status === 'error') {
    msg((job.error || 'pull failed') + (job.hint ? (' — ' + job.hint) : '') + (errTxt ? (' · ' + errTxt) : ''), false);
    return;
  }
  if (n === 0) {
    var expired = /session expired|reconnect Airbnb|OTP|Connect Airbnb session/i.test(errTxt + ' ' + (job.reconnectHint || ''));
    msg('Airbnb pull saved 0 PDFs from ' + codes + ' Hosthub code(s)' +
      (errTxt ? (' — ' + errTxt) : '') +
      (job.reconnectHint ? (' — ' + job.reconnectHint) : (expired ? ' — click Connect Airbnb, enter the email code, then Pull again' : '')), false);
  } else {
    msg('Pulled ' + n + ' Airbnb PDF(s) from ' + codes + ' Hosthub code(s)' +
      (errTxt ? (' · notes: ' + errTxt) : ''), true);
  }
};
window.piWatchPullJob = async function (id, codeCount) {
  var deadline = Date.now() + 95 * 60 * 1000;
  while (Date.now() < deadline) {
    await new Promise(function (ok) { setTimeout(ok, 2000); });
    var res = await fetch('/api/platform-invoices/pull/' + encodeURIComponent(id));
    var raw = await res.text();
    var r = piPullParseResponse(res, raw);
    if (!res.ok) throw new Error((r && r.error) || 'pull status failed');
    var job = (r && r.job) || r || {};
    if (job.hint) msg(job.hint, job.status !== 'error');
    if (job.status === 'done' || job.status === 'error') {
      piPullFinishMsg(job, codeCount);
      await piHealth();
      await piReload();
      return;
    }
  }
  throw new Error('Pull is still running. Click Pull Airbnb again to watch progress — do not start Connect unless the session expired.');
};
